    result=json.loads((HERE/'results.json').read_text());validation=json.loads((HERE/'validation.json').read_text());assert validation['status']=='passed';d=Data();entry,exit,config=load_models();final=json.loads((HERE/'final-fit.json').read_text());summary=json.loads((HERE/'candidate-summary.json').read_text());features=json.loads((HERE/'feature-summary.json').read_text());news=json.loads((HERE/'news-manifest.json').read_text());audits=json.loads((HERE/'selection-audit.json').read_text());diagnostic=result['exit_with_teacher_entries_diagnostic']
    i=final['validation_teacher_entries'][0];x=d.entry_rows([i])[0];entry_input={'stage':'entry','historical_example_only':True,'eligible':True,'features':{n:float(v) if np.isfinite(v) else None for n,v in zip(d.entry_names,x)}};x=d.exit_rows([i],[i+6])[0];exit_input={'stage':'exit','historical_example_only':True,'holding_step':6,'features':{n:float(v) if np.isfinite(v) else None for n,v in zip(d.exit_names,x)}};save('example-entry-input.json',entry_input);save('example-exit-input.json',exit_input);save('example-entry-output.json',entry_action(entry,config,entry_input['features']));save('example-exit-output.json',exit_action(exit,config,exit_input['features'],6))
    card={'separate_models':2,'entry':{'raw_market_features':len(d.market_names),'raw_news_features':len(d.news_names),'retained_news_features':sum('news' in n for n in entry['preprocess'].names),'training_states':final['entry_training_states'],'positive_entry_targets':final['entry_training_positives'],'news_available_training_states':final['training_news_states'],'news_available_positive_targets':final['training_news_positive_targets'],'selected_updates':entry['updates'],'completed_updates':4000,'parameters':sum(p.size for p in entry['model'].params)},'exit':{'raw_market_features':len(d.market_names),'trade_state_features':len(TRADE_NAMES),'news_features':0,'training_entries':final['exit_training_entries'],'training_rows':final['exit_training_rows'],'selected_updates':exit['updates'],'completed_updates':4000,'parameters':sum(p.size for p in exit['model'].params)},'policy':config,'new_model_not_prospectively_tested':True};save('model-card.json',card)
    lines=['TWO SUPERVISED MODELS: ENTRY WITH NEWS, EXIT WITHOUT NEWS','Completed November 14, 2026, Europe/Paris. Offline research artifacts.','',
    'Request and implemented target','Scan every recorded native token for rolling24h price gains >=10%. The market','database stores historical prices, so the percentage is calculated from same-','venue five-minute closing observations exactly24h apart. Repeated qualifying','readings are grouped with one anchor per token per24h. No SMA crossover is','required for target discovery or live entry; SMA measurements remain features.','',
    'For each anchor, the teacher searches entries in the preceding24h through the','anchor and exits5m to24h AFTER each entry. It chooses the maximum executable','gross-return pair. An entry target can be one5m bar away if it preserves >=95%','of that optimum. The exit model trains on exactly these same positive entry','points, each with its own optimal exit. Non-target eligible periods are entry','negatives; incomplete/censored teacher searches are excluded, not mislabeled.','The >=10% screen is a future training label, never a live-entry gate.','',
    'Execution','Both decisions use five-minute completed bars. The decision arrives5 seconds','after close; a hypothetical fill uses the following minute open55 seconds later.','The maximum holding period is24h from the actual entry fill. The exit is chosen','every5m; only its upper bound is fixed. A missing terminal open may retry for','up to30m, recorded separately. Entry uses100 USD and requires at least10,000 USD','approximate quote volume in the preceding minute. Fees, funding payments and','slippage are zero. One position per symbol; no positions bridge archive gaps.','Reported P&L sums per-symbol100 USD trades, not a shared-capital account ROI.','',
    'Dataset',f'{summary["scanned_symbols"]} native token symbols; {summary["all_qualifying_5m_observations"]:,} qualifying five-minute readings.',f'{summary["teacher_rallies"]} usable target rallies across {summary["teacher_symbols"]} tokens; {summary["unique_teacher_entries"]} unique exact optimal entry points before the near-optimal tolerance.',f'{summary["mature_eligible_states"]:,} mature eligible classification states, including {summary["mature_good_entry_states"]} positive entry targets.',f'Excluded rally searches: {summary["exclusions"]}.',f'{features["states"]:,} global five-minute states; {features["coverage"]["spot_candles"]:,} spot candles; {features["coverage"]["derivative_states"]:,} derivative snapshots; {features["coverage"]["quote_states"]:,} usable book snapshots.',f'{news["documents"]:,} account-scoped news documents. Earliest news availability: {news["first"]}.','News unavailable before the feed existed is missing, not neutral sentiment.','Book coverage is sparse; some inputs disappear under train-only preprocessing.','Whale-source news is reporting, not a verified wallet or exchange-flow ledger.','',
    'Independent models',f'Entry: {len(d.market_names)} market inputs plus {len(d.news_names)} news inputs. Final fitting used {final["entry_training_states"]:,} states and {final["entry_training_positives"]} positive targets; {final["training_news_positive_targets"]} positive targets had news-feed coverage.',f'Exit: {len(d.market_names)} market inputs plus {len(TRADE_NAMES)} trade-state inputs. It trained on {final["exit_training_entries"]} of the same positive entry points. There are zero news inputs.','The exit sees entry-relative return, elapsed/remaining holding time, running','gain/drawdown/rebound since entry, and entry price. No entry-model score or','news-trained hidden representation is passed into it.','Both networks have hidden layers64/32 and run4,000 class-balanced BCE updates.',f'Validation retained entry checkpoint {entry["updates"]} and exit checkpoint {exit["updates"]}.','Scores are classifier scores, not calibrated probabilities of a profitable trade.','',
    'Chronological replay:100 USD per trade, fees excluded','Policy                               Trades      Gross USD']
    for p,label in [('two_stage','Learned entry + learned exit'),('entry_fixed24h','Same entry model + fixed24h'),('cash','Cash')]:
        s=result['comparisons'][p]['all'];lines.append(f'{label:37s}{s["trades"]:6d}{s["gross_profit_usd"]:15.2f}')
    lines+=['The fixed24h baseline uses the same entry model and threshold but enforces its','own position occupancy; different holding times change which later entries fit.','',
    'News-specific qualification','The older fitted folds had no news-era observations in their training sets.',f'Only {validation["news_trained_test_folds"]} test fold(s) used a model trained with retained news features.']
    s=result['comparisons']['two_stage']['news_trained_model'];lines.append(f'That subset produced {s["gross_profit_usd"]:+.2f} USD over {s["trades"]} trades. The overall result is not evidence that news improved the strategy.')
    lines+=['','Per-fold results']
